static void MimeCMS_free(MimeClosure crypto_closure) {
  if (!crypto_closure) return;

  MimeCMSdata* data = crypto_closure.AsMimeCMSData();
  if (!data) {
    return;
  }

  if (data->decoded_buffer) {
    PR_Free(data->decoded_buffer);
    data->decoded_buffer = nullptr;
  }

  delete data;
}
